from ortools.sat.python import cp_model
import itertools

n = 16
forced_edges = set([(6,14), (13,14), (0,12), (2,11), (2,10), (8,14), (7,14), (6,15), (5,13), (12,15), (2,14), (0,11), (0,8), (8,15), (14,15), (4,5), (5,7), (2,13), (0,2), (0,1), (0,10), (0,5), (10,11), (3,7)])

# Build adjacency for forced edges
adj_forced = [set() for _ in range(n)]
for u,v in forced_edges:
    adj_forced[u].add(v)
    adj_forced[v].add(u)

model = cp_model.CpModel()

# Create variables x[i][j] for i<j
x = {}
for i in range(n):
    for j in range(i+1, n):
        x[(i,j)] = model.NewBoolVar(f"x_{i}_{j}")

# Fix forced edges
for e in forced_edges:
    model.Add(x[e] == 1)

# MIS constraints: for each 6-set with no forced edge, at least one edge inside
bad_6sets = []
for S in itertools.combinations(range(n), 6):
    has_forced = False
    s = set(S)
    for u in S:
        for v in adj_forced[u]:
            if v in s and u < v:
                has_forced = True
                break
        if has_forced:
            break
    if not has_forced:
        bad_6sets.append(S)

print("Bad 6-sets:", len(bad_6sets))

for S in bad_6sets:
    edges_in_S = []
    for i in range(len(S)):
        for j in range(i+1, len(S)):
            u, v = S[i], S[j]
            if u < v:
                edges_in_S.append(x[(u,v)])
            else:
                edges_in_S.append(x[(v,u)])
    model.Add(sum(edges_in_S) >= 1)

# Connectivity constraints
print("Adding connectivity constraints...")
other_vertices = [v for v in range(n) if v != 0]
count = 0
for mask in range(1, 1 << (n-1)):  # exclude empty and full
    S = [0] + [other_vertices[i] for i in range(n-1) if (mask >> i) & 1]
    S_set = set(S)
    crossing = []
    for u in S:
        for v in range(n):
            if v not in S_set:
                if u < v:
                    crossing.append(x[(u,v)])
                elif v < u:
                    crossing.append(x[(v,u)])
    model.Add(sum(crossing) >= 1)
    count += 1
    if count % 10000 == 0:
        print(f"  Added {count} connectivity constraints")

print(f"Total connectivity constraints: {count}")

# Solve
solver = cp_model.CpSolver()
solver.parameters.max_time_in_seconds = 60.0
solver.parameters.num_search_workers = 8
print("Solving...")
status = solver.Solve(model)
print("Status:", status, "OPTIMAL:", cp_model.OPTIMAL, "FEASIBLE:", cp_model.FEASIBLE, "INFEASIBLE:", cp_model.INFEASIBLE)

if status == cp_model.OPTIMAL or status == cp_model.FEASIBLE:
    edges = []
    for i in range(n):
        for j in range(i+1, n):
            if solver.Value(x[(i,j)]) == 1:
                edges.append((i,j))
    print("Solution edges:", len(edges))
    print(edges)

