    # Check connectivity
    adj = [set() for _ in range(n)]
    for u,v in edges:
        adj[u].add(v)
        adj[v].add(u)
    import collections
    visited = [False]*n
    q = collections.deque([0])
    visited[0] = True
    while q:
        u = q.popleft()
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                q.append(v)
    print("Connected?", all(visited))
